<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class InvoiceSession extends Model{protected $fillable=['invoice_id','title','description','notes','sort_order','discount_type','discount_value','tax_rate','subtotal','discount_amount','tax_amount','net_total'];protected function casts():array{return ['discount_value'=>'decimal:2','tax_rate'=>'decimal:4','subtotal'=>'decimal:2','discount_amount'=>'decimal:2','tax_amount'=>'decimal:2','net_total'=>'decimal:2'];}public function invoice(){return $this->belongsTo(Invoice::class);}public function items(){return $this->hasMany(InvoiceItem::class)->orderBy('sort_order');}}
